-- Generated by tools/build-slot-scan.mjs. One download; no mutable module fetch.
-- Standalone read-only diagnostic. Compatible with the current live control client.
local Players = game:GetService("Players")
local Http = game:GetService("HttpService")
local player = Players.LocalPlayer
assert(player, "Run this in a Roblox client")
assert(game.PlaceId == 4111023553, "Run the slot scanner at the character-selection menu")
local Scan = (function()
-- Passive character-card reader. No input hooks, clicks, remotes or uploads.
local Scan = { VERSION = "0.2.1", MAX_CARDS = 60, MAX_CARD_NODES = 160,
    MAX_CARD_LABELS = 24, MAX_DEPTH = 12, MAX_TEXT_BYTES = 100000 }
local listPath = { "LoadingGui", "Overlay", "Columns", "MainFrame", "Slots", "SlotScroll" }
local aliases = {
    charactername = "characterName", name = "characterName",
    race = "race", level = "level", power = "level", oath = "oath", origin = "origin",
    realm = "location", location = "location", luminant = "location", region = "location",
    playtime = "playtime", lastplayed = "lastPlayed", slot = "slotLabel",
    memento = "memento", ironrace = "ironRace",
}
local metadataFields = { race = "baseRace", origin = "baseOrigin", ironRace = "ironRace", memento = "memento" }
local function short(value, limit)
    if type(value) ~= "string" and type(value) ~= "number" then return nil end
    return tostring(value):gsub("[%z\1-\31]", " "):sub(1, limit or 160)
end
local function lower(value) return tostring(value):lower():gsub("[%s_%-]", "") end
local function plain(value)
    local text = tostring(value):gsub("<[^>]*>", "")
        :gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&quot;", '"'):gsub("&apos;", "'"):gsub("&amp;", "&")
    text = text:gsub("%s+", " "):match("^%s*(.-)%s*$")
    if text == "" or text == "???" or text == "?" then return nil end
    return short(text)
end
local function slotId(value)
    return type(value) == "string" and #value <= 3 and value:match("^[A-Z]+$") ~= nil
end
local function children(object)
    local ok, result = pcall(object.GetChildren, object)
    return ok and result or {}
end
local function uniqueChild(object, name)
    local found
    for _, child in ipairs(children(object)) do
        if child.Name == name then
            if found then return nil end
            found = child
        end
    end
    return found
end
local function excluded(object)
    local name = lower(object.Name)
    return object:IsA("ViewportFrame") or object:IsA("TextBox") or not object:IsA("GuiObject")
        or name:find("chat", 1, true) or name:find("friend", 1, true)
        or name:find("social", 1, true) or name:find("delete", 1, true)
end
local function setField(card, key, value, source)
    if value == nil or card.conflicts[key] then return end
    if card[key] ~= nil and card[key] ~= value then
        card[key] = nil; card.conflicts[key] = true; card.fieldSources[key] = nil
        return
    end
    card[key] = value; card.fieldSources[key] = source
end
local function readLabel(card, name, raw, path, shown)
    local text = plain(raw)
    if not text then return end
    local key = aliases[lower(name)]
    -- Keep alternate metadata separate from the values displayed on the card.
    if metadataFields[key] then setField(card, metadataFields[key], text, path) end
    if not shown then return end
    if key == "ironRace" then key = "race" end
    if key == "memento" then key = "origin" end
    local level = text:match("^[Ll][Vv]%.?%s*(%d+)%s+")
    local prefix, race = raw:match("^(.-)<font[^>]*>(.-)</font>")
    local coloredRace = prefix and (plain(prefix) == nil
        or plain(prefix):match("^[Ll][Vv]%.?%s*%d+$")) and plain(race) or nil
    if key == "level" then
        local number = text:match("^%d+$") or text:match("^[Ll][Vv]%.?%s*(%d+)") or text:match("^[Pp]ower%s+(%d+)")
        if number then setField(card, "level", tonumber(number), path) end
    elseif key == "race" and (coloredRace or level) then
        setField(card, "race", coloredRace, path .. "#colored-race")
        setField(card, "summary", text, path)
    elseif key then
        setField(card, key, text, path)
    end
    -- Some cards combine level, colored race and oath on one line. Preserve the
    -- complete line; only split the race when markup explicitly isolates it.
    if level then
        setField(card, "level", tonumber(level), path)
        setField(card, "summary", text, path)
        if coloredRace then setField(card, "race", coloredRace, path .. "#colored-race") end
    end
end
local function captureCard(object, result, yieldStep)
    local card = { slot = object.Name, source = "menu-card", confirmed = false, cardVisible = object.Visible ~= false,
        labels = {}, fieldSources = {}, conflicts = {}, missing = {}, warnings = {}, visited = 0, truncated = false }
    -- Visibility is relative to the card; clipping/scrolling never discards an offscreen slot.
    local queue = { { object = object, path = "", depth = 0, shown = true } }
    local head = 1
    while head <= #queue do
        local item = queue[head]; head += 1
        local node = item.object
        card.visited += 1; result.visited += 1
        if not excluded(node) then
            if node:IsA("TextLabel") or node:IsA("TextButton") then
                local ok, value = pcall(function() return node.Text end)
                local text = ok and type(value) == "string" and plain(value) or nil
                if text then
                    local raw = short(value, 512)
                    local cost = #raw + #text + #item.path + 120
                    if #card.labels < Scan.MAX_CARD_LABELS and result.textBytes + cost <= Scan.MAX_TEXT_BYTES then
                        local transparent = type(node.TextTransparency) == "number" and node.TextTransparency >= 1
                        local shown = item.shown and not transparent
                        local label = { name = short(node.Name, 60), path = item.path, text = text,
                            visibleWithinCard = shown, textTransparency = node.TextTransparency }
                        if raw ~= text then label.rawText = raw end
                        card.labels[#card.labels + 1] = label
                        result.labelCount += 1; result.textBytes += cost
                        readLabel(card, node.Name, raw, item.path, shown)
                    else card.truncated = true end
                end
            end
            -- Reject avatar trees, scripts, layouts and editable text before enqueueing.
            for _, child in ipairs(children(node)) do
                if not excluded(child) then
                    if item.depth >= Scan.MAX_DEPTH or #queue >= Scan.MAX_CARD_NODES then card.truncated = true
                    else queue[#queue + 1] = { object = child, shown = item.shown and child.Visible ~= false,
                        path = (item.path == "" and child.Name or item.path .. "/" .. child.Name):sub(1, 220), depth = item.depth + 1 } end
                end
            end
        end
        if yieldStep and result.visited % 80 == 0 then yieldStep() end
    end
    if card.slotLabel and card.slotLabel ~= card.slot then card.warnings[#card.warnings + 1] = "slot-label-mismatch" end
    for _, key in ipairs({ "characterName", "level", "race", "location" }) do
        if card[key] == nil then card.missing[#card.missing + 1] = key end
    end
    for key in pairs(card.conflicts) do card.warnings[#card.warnings + 1] = "conflicting-" .. key end
    table.sort(card.warnings)
    card.complete = #card.missing == 0 and #card.warnings == 0 and not card.truncated
    if card.truncated then result.truncated = true end
    return card
end
function Scan.collect(playerGui, yieldStep)
    local result = { version = Scan.VERSION, status = "NO_SLOT_LIST", cards = {}, visited = 0,
        labelCount = 0, textBytes = 0, truncated = false, completeCards = 0, scope = table.concat(listPath, "/") }
    if not playerGui then return result end
    local list = playerGui
    for _, name in ipairs(listPath) do
        list = uniqueChild(list, name)
        if not list then return result end
    end
    local cards = {}
    for _, child in ipairs(children(list)) do
        if slotId(child.Name) and child:IsA("GuiObject") and not excluded(child) then cards[#cards + 1] = child end
    end
    table.sort(cards, function(a, b) return #a.Name == #b.Name and a.Name < b.Name or #a.Name < #b.Name end)
    if #cards == 0 then result.status = "WAITING_FOR_CARDS"; return result end
    local seen = {}
    for _, object in ipairs(cards) do
        if #result.cards >= Scan.MAX_CARDS then result.truncated = true; break end
        local card = captureCard(object, result, yieldStep)
        if seen[card.slot] then
            card.complete = false; card.warnings[#card.warnings + 1] = "duplicate-slot"
            local previous = seen[card.slot]
            previous.complete = false; previous.warnings[#previous.warnings + 1] = "duplicate-slot"
        else seen[card.slot] = card end
        result.cards[#result.cards + 1] = card
    end
    for _, card in ipairs(result.cards) do if card.complete then result.completeCards += 1 end end
    result.status = result.truncated and "PARTIAL_CARDS"
        or (result.completeCards == #result.cards and "CARDS_CAPTURED_UNCONFIRMED" or "PARTIAL_CARD_DETAILS")
    return result
end
return Scan

end)()
local result = Scan.collect(player:FindFirstChild("PlayerGui"), function() task.wait() end)
result.accountId = tostring(player.UserId)
result.capturedAt = os.time()
result.placeId = game.PlaceId
local raw = Http:JSONEncode(result)
assert(#raw < 400000, "Menu report exceeded the safety limit")
getgenv().CLAW_SLOT_SCAN = result
local ok = pcall(function()
    if not isfolder("CLAW_CONTROL") then makefolder("CLAW_CONTROL") end
    local path = "CLAW_CONTROL/menu-" .. tostring(player.UserId) .. ".json"
    writefile(path, raw)
    assert(readfile(path) == raw)
end)
print("[CLAW SCAN] v" .. Scan.VERSION .. " | " .. result.status .. " | " .. #result.cards .. " cards | "
    .. result.completeCards .. " with name/level/race/location | " .. result.labelCount .. " labels")
for _, card in ipairs(result.cards) do
    print("[CLAW SLOT " .. card.slot .. "] " .. (card.characterName or "name not read")
        .. " | Lv. " .. tostring(card.level or "?") .. " " .. (card.race or "race not read")
        .. " | " .. (card.oath or "") .. " | " .. (card.origin or "") .. " | " .. (card.location or "location not read")
        .. " | played " .. (card.playtime or "?") .. " | last " .. (card.lastPlayed or "?"))
end
print(ok and "[CLAW SCAN] Saved in Volt workspace/CLAW_CONTROL. No selection or teleport was sent."
    or "[CLAW SCAN] File save unavailable; report is in getgenv().CLAW_SLOT_SCAN")
return result
